// Zella - Spam Response: decide where each claimed item goes. The incident is already detected, scored, saved and
// (for calls) screened by the database before this runs; this only routes the follow-up:
//   log          nothing for anyone to do now (recorded as processed)
//   alert        tell the team (high risk, or medium when the business asked for medium alerts)
//   investigate  look closer first: a sender seen before, at other businesses, flooding, or an ambiguous message
// The database checks everything again when the result comes back, so a wrong route here can't cause harm.
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const j = $json && typeof $json === 'object' ? $json : {};

if (j.kind === 'report') {
  if (!uuid.test(String(j.business_id || '')) || !/^\d{4}-\d{2}-\d{2}$/.test(String(j.week_start || ''))) return { json: { kind: 'skip', why: 'bad_report' } };
  return { json: { kind: 'report', business_id: j.business_id, business_name: String(j.business_name || '').slice(0, 120), week_start: j.week_start, stats: j.stats && typeof j.stats === 'object' ? j.stats : {} } };
}
if (j.kind !== 'incident' || !uuid.test(String(j.incident_id || '')) || !uuid.test(String(j.claim || ''))) return { json: { kind: 'skip', why: 'not_an_item' } };

const inc = j.incident && typeof j.incident === 'object' ? j.incident : {};
const f = j.facts && typeof j.facts === 'object' ? j.facts : {};
const p = j.policy && typeof j.policy === 'object' ? j.policy : {};
const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const seenBefore = n(f.here_prior) > 0 || n(f.here_confirmed) > 0 || n(f.other_businesses) > 0;
const flooding = n(inc.occurrences) >= Math.max(2, n(p.flood_alert_at) || 20);
const ai = j.ai_request && typeof j.ai_request === 'object' && Array.isArray(j.ai_request.messages) ? j.ai_request : null;

let route = 'log';
if (f.allowlisted === true) route = 'log';
else if (inc.risk_level === 'high') route = seenBefore || flooding ? 'investigate' : 'alert';
else if (inc.risk_level === 'medium') route = ai || seenBefore ? 'investigate' : p.notify_medium === true ? 'alert' : 'log';

return {
  json: {
    kind: 'incident', route, incident_id: j.incident_id, claim: j.claim,
    risk_level: inc.risk_level || null, channel: inc.channel || null, facts: f,
    ai_request: route === 'investigate' ? ai : null,
    finish: { p_incident_id: j.incident_id, p_claim: j.claim, p_result: { route } },
  },
};

// Zella - Spam Response: the weekly summary for one business, from the counts the database prepared. Posted once per
// week (the database refuses a second one); emailed only if the person turned that on in their notification settings.
const r = $json;
const s = r.stats || {};
const n = (v) => (Number.isFinite(Number(v)) ? Math.max(0, Math.round(Number(v))) : 0);
const total = n(s.total);
const plural = (k, one, many) => k + ' ' + (k === 1 ? one : many);
const parts = [['calls', 'call', 'calls'], ['texts', 'text', 'texts'], ['emails', 'email', 'emails'], ['bookings', 'booking', 'bookings']]
  .filter(([k]) => n(s[k]) > 0).map(([k, one, many]) => plural(n(s[k]), one, many));
const lines = [
  plural(total, 'suspicious contact was', 'suspicious contacts were') + ' flagged last week' + (parts.length ? ' (' + parts.join(', ') + ')' : '') + '.',
  n(s.high) ? plural(n(s.high), 'was', 'were') + ' high risk.' : null,
  n(s.blocked) ? plural(n(s.blocked), 'was', 'were') + ' blocked, screened or restricted.' : null,
  n(s.held) ? plural(n(s.held), 'booking was', 'bookings were') + ' held for your team to confirm.' : null,
  n(s.confirmed) || n(s.not_spam) ? 'Your team confirmed ' + n(s.confirmed) + ' as spam and marked ' + n(s.not_spam) + ' as not spam.' : null,
  n(s.open) ? plural(n(s.open), 'incident is', 'incidents are') + ' still waiting for review.' : 'Nothing is waiting for review.',
  'Open Spam protection for details.',
].filter(Boolean);
return {
  json: {
    body: {
      p_business_id: r.business_id,
      p_week_start: r.week_start,
      p_title: 'Spam protection: ' + plural(total, 'incident', 'incidents') + ' last week',
      p_body: lines.join(' '),
    },
  },
};

// Zella - Spam Response: repeat-offender check for incidents that need a closer look. Uses only the counts the
// database handed over (never another business's name or messages) and writes down what was found. Any action
// that follows (a temporary restriction, a platform alert) is decided by the database's approved policy.
const s = $json;
const f = s.facts || {};
const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const findings = [];
if (n(f.here_confirmed) > 0) findings.push('confirmed_here_' + n(f.here_confirmed));
else if (n(f.here_prior) > 0) findings.push('seen_here_before');
if (n(f.other_confirmed) > 0) findings.push('confirmed_elsewhere_' + n(f.other_confirmed));
else if (n(f.other_businesses) > 0) findings.push('seen_elsewhere');
if (f.platform_rule === true) findings.push('platform_rule');
const repeat = n(f.here_confirmed) >= 2 || n(f.other_confirmed) >= 2;
return {
  json: {
    ...s,
    finish: { ...s.finish, p_result: { ...s.finish.p_result, route: 'investigate', repeat_offender: repeat, findings } },
  },
};

// Zella - Spam Response: read the AI's second opinion. It is only a suggestion shown to the team: the database keeps
// it (if this incident was allowed an AI review at all) and never blocks or changes anything because of it.
// If the AI is down or answers badly, the incident is still processed without it, so alerts are never held up.
const s = $('Check repeat offender').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const out = (extra) => ({ json: { ...s, finish: { ...s.finish, p_result: { ...s.finish.p_result, ...extra } } } });
if (!(status >= 200 && status < 300) || !Array.isArray(b.content)) return out({ ai_error: 'AI unavailable (' + (status || 'no answer') + ')' });
const text = b.content.filter((c) => c && c.type === 'text').map((c) => c.text).join('');
let d;
try { d = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, '').trim()); } catch (e) { return out({ ai_error: 'Unreadable AI answer' }); }
if (!d || typeof d !== 'object' || !['spam', 'not_spam', 'unsure'].includes(d.label)) return out({ ai_error: 'Unreadable AI answer' });
const confidence = Number(d.confidence);
return out({
  ai: {
    label: d.label,
    confidence: Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : null,
    reason: typeof d.reason === 'string' ? d.reason.replace(/\s+/g, ' ').trim().slice(0, 200) : '',
  },
});
